package transpose

import "strings"

// Transpose returns the input text transposed: rows become columns and
// columns become rows.
//
// Rows of differing lengths are treated as if padded with spaces, but only
// on the left of the output. Trailing spaces (i.e. padding on the right of
// an output row) are not emitted, while real spaces from the input are kept.
func Transpose(input []string) []string {
	if len(input) == 0 {
		return []string{}
	}

	width := 0
	for _, row := range input {
		if len(row) > width {
			width = len(row)
		}
	}

	result := make([]string, width)
	for col := 0; col < width; col++ {
		var b strings.Builder
		lastReal := -1
		for rowIdx, row := range input {
			if col < len(row) {
				b.WriteByte(row[col])
				lastReal = rowIdx
			} else {
				b.WriteByte(' ')
			}
		}
		if lastReal >= 0 {
			result[col] = b.String()[:lastReal+1]
		} else {
			result[col] = ""
		}
	}
	return result
}

